WITH cust_orders AS ( SELECT c.c_customer_sk, c.c_first_name, c.c_last_name, first_sales.d_date AS first_sales_date, last_review.d_date AS last_review_date, date_diff('day', first_sales.d_date, last_review.d_date) AS days_between, ws.ws_net_paid, ws.ws_order_number, ws.ws_sold_date_sk, s.s_store_name, ROW_NUMBER() OVER (PARTITION BY c.c_customer_sk ORDER BY ws.ws_sold_date_sk DESC) AS rn FROM customer c LEFT JOIN date_dim first_sales ON c.c_first_sales_date_sk = first_sales.d_date_sk LEFT JOIN date_dim last_review ON c.c_last_review_date = last_review.d_date_sk LEFT JOIN web_sales ws ON ws.ws_bill_customer_sk = c.c_customer_sk LEFT JOIN store s ON ws.ws_warehouse_sk = s.s_store_sk ), cust_agg AS ( SELECT co.c_customer_sk, co.c_first_name, co.c_last_name, MAX(co.first_sales_date) AS first_sales_date, MAX(co.last_review_date) AS last_review_date, MAX(co.days_between) AS days_between, SUM(co.ws_net_paid) AS total_net_paid, COUNT(DISTINCT co.ws_order_number) AS total_orders, MAX(CASE WHEN co.rn = 1 THEN co.s_store_name END) AS recent_store_name FROM cust_orders co GROUP BY co.c_customer_sk, co.c_first_name, co.c_last_name ) SELECT ca.c_customer_sk, ca.c_first_name, ca.c_last_name, ca.first_sales_date, ca.last_review_date, ca.days_between, ca.total_net_paid, ca.total_orders, ca.recent_store_name, CASE WHEN ca.days_between IS NULL THEN 'No Review' WHEN ca.days_between <= 30 THEN 'Active' WHEN ca.days_between <= 180 THEN 'Moderately Active' ELSE 'Inactive' END AS activity_tier, RANK() OVER (ORDER BY ca.total_net_paid DESC) AS revenue_rank, DENSE_RANK() OVER (PARTITION BY CASE WHEN ca.days_between IS NULL THEN 'No Review' WHEN ca.days_between <= 30 THEN 'Active' WHEN ca.days_between <= 180 THEN 'Moderately Active' ELSE 'Inactive' END ORDER BY ca.total_net_paid DESC) AS tier_dense_rank FROM cust_agg ca WHERE ca.total_net_paid > 0 ORDER BY ca.total_net_paid DESC LIMIT 25
